/**
 * Read a forum attribute. During `app.initializers` (when we first apply
 * styles to avoid a flash) core hasn't built `app.forum` from the payload yet,
 * so fall back to reading the bootstrap payload directly. Once booted (e.g. the
 * modal's "reset to default"), `app.forum.attribute()` is used.
 */
function forumAttribute(name) {
  const forum = app.forum;
  if (forum && typeof forum.attribute === 'function') {
    return forum.attribute(name);
  }
  const resources = app.data?.resources ?? [];
  const forumRecord = resources.find(r => r && r.type === 'forums');
  return forumRecord?.attributes?.[name];
}

/** Admin-configured sitewide default scale. */
export function adminDefaultScale() {
  return clampScale(parseInt(forumAttribute('linkrobinsFontScale') ?? String(TEXT_DEFAULT), 10));
}

/** Admin-configured sitewide default interface size. */
export function adminDefaultUi() {
  return forumAttribute('linkrobinsFontSizerUi') === 'large';
}

/**
 * Admin-configured base sizes. Unlike scale and UI size these carry no user
 * override (no cookie): they describe the theme's starting sizes, so they are
 * read from the payload and applied once at boot.
 */
export function adminBases() {
  return {
    base: clampBase(parseInt(forumAttribute('linkrobinsFontSizerTextBase') ?? '', 10), BASE_DEFAULTS.base),
    small: clampBase(parseInt(forumAttribute('linkrobinsFontSizerTextSmall') ?? '', 10), BASE_DEFAULTS.small),
    title: clampBase(parseInt(forumAttribute('linkrobinsFontSizerTextTitle') ?? '', 10), BASE_DEFAULTS.title)
  };
}

/** Resolve the effective state from cookies, falling back to admin defaults. */
export function loadState() {
  const cookieText = getCookie(COOKIE_TEXT);
  const cookieUI = getCookie(COOKIE_UI);
  state.textScale = cookieText !== null ? clampScale(parseInt(cookieText, 10)) : adminDefaultScale();
  state.uiLarge = cookieUI !== null ? cookieUI === 'large' : adminDefaultUi();
}
export function applyText() {
  applyTextScale(state.textScale);
}
export function applyUi() {
  applyUiScale(state.uiLarge);
}
export function applyAll() {
  applyText();
  applyTextBases(adminBases());
  applyUi();
}
export function setTextScale(value) {
  state.textScale = clampScale(value);
  setCookie(COOKIE_TEXT, String(state.textScale));
  applyText();
}
export function setUiLarge(value) {
  state.uiLarge = value;
  setCookie(COOKIE_UI, value ? 'large' : 'default');
  applyUi();
}

/** Restore the admin-configured sitewide defaults and persist them. */
export function resetToDefault() {
  state.textScale = adminDefaultScale();
  state.uiLarge = adminDefaultUi();
  setCookie(COOKIE_TEXT, String(state.textScale));
  setCookie(COOKIE_UI, state.uiLarge ? 'large' : 'default');
  applyAll();
}
flarum.reg.add('linkrobins-font-sizer', 'forumState', { state: state,adminDefaultScale: adminDefaultScale,adminDefaultUi: adminDefaultUi,adminBases: adminBases,loadState: loadState,applyText: applyText,applyUi: applyUi,applyAll: applyAll,setTextScale: setTextScale,setUiLarge: setUiLarge,resetToDefault: resetToDefault, });